{
  "tasks": [
    {
      "task_id": "T1",
      "title": "按项目统计任务数量与工时分布",
      "business_question": "各项目包含的任务数量是多少？各项目的平均工时和总工时分别是多少？",
      "priority": "P0",
      "priority_reason": "直接响应“探索主要分布”的核心需求，通过分组聚合揭示不同项目间的资源投入差异。删除后无法回答项目层面的概况问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_work_hours"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_work_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T2",
      "title": "按状态统计任务数量与工时分布",
      "business_question": "各状态（如进行中、已完成等）的任务数量是多少？各状态的平均工时是多少？",
      "priority": "P0",
      "priority_reason": "直接响应“探索主要分布与差异”的核心需求，通过状态维度分析任务生命周期中的分布情况。删除后无法回答状态层面的概况问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "status_task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "status_avg_work_hours"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T3",
      "title": "整体数据概况与时间跨度",
      "business_question": "数据集的总任务数、唯一项目数、唯一状态数是多少？创建日期的年份分布如何？",
      "priority": "P1",
      "priority_reason": "提供基础元数据和整体规模，辅助理解前两个任务的上下文。属于补充性分析，虽有助于全面性但非核心差异比较的唯一依据。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "created_year"
          }
        },
        {
          "step_id": "S2",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "total_tasks"
              },
              {
                "function": "distinct_count",
                "field": "field_0002",
                "alias": "unique_projects"
              },
              {
                "function": "distinct_count",
                "field": "field_0003",
                "alias": "unique_statuses"
              }
            ]
          }
        }
      ]
    }
  ]
}
